static const chs_oracle_row *chs_oracle_find(uint32_t cp) {
    size_t lo = 0, hi = CHS_ORACLE_CODEPOINTS;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (chs_oracle_keys[mid] < cp) lo = mid + 1;
        else hi = mid;
    }
    if (lo < CHS_ORACLE_CODEPOINTS && chs_oracle_keys[lo] == cp)
        return &chs_oracle[lo];
    return 0;
}

